// Loads the pre-built catalogue/tree JSON (generated by scripts/build_catalog.py)
// and builds the small in-memory indices the rest of the app queries synchronously.
// This is the only network activity at startup -- no book content is ever
// fetched until the reader opens a specific book.

let catalog = [];       // flat array of book records: {p,l,c,a,t,s, _search}
let categories = {};    // category code -> display name
let tree = {};          // library -> category -> [{n, s}]  (ground truth from disk)
let libraries = [];     // [{id, label, categoryCount, bookCount}]

let byPath = new Map();          // path -> catalog entry
let byLibCategory = new Map();   // "library|category" -> catalog entry[]

export async function loadLibraryData() {
  const [catalogRes, categoriesRes, treeRes, librariesRes] = await Promise.all([
    fetch("data/catalog.json"),
    fetch("data/categories.json"),
    fetch("data/tree.json"),
    fetch("data/libraries.json"),
  ]);
  for (const res of [catalogRes, categoriesRes, treeRes, librariesRes]) {
    if (!res.ok) throw new Error(`Failed to load ${res.url} (HTTP ${res.status})`);
  }
  catalog = await catalogRes.json();
  categories = await categoriesRes.json();
  tree = await treeRes.json();
  libraries = await librariesRes.json();

  byPath = new Map();
  byLibCategory = new Map();
  for (const entry of catalog) {
    entry._search = {
      author: (entry.a || "").toLocaleLowerCase(),
      title: (entry.t || "").toLocaleLowerCase(),
      category: `${entry.c || ""} ${categories[entry.c] || ""}`.toLocaleLowerCase(),
      collection: (entry.l || "").toLocaleLowerCase(),
      path: entry.p.toLocaleLowerCase(),
    };
    entry._search.names = `${entry._search.author} ${entry._search.title}`;
    byPath.set(entry.p, entry);
    const key = `${entry.l}|${entry.c}`;
    if (!byLibCategory.has(key)) byLibCategory.set(key, []);
    byLibCategory.get(key).push(entry);
  }
  for (const list of byLibCategory.values()) {
    list.sort((a, b) => (a.a + a.t).localeCompare(b.a + b.t, "ru"));
  }

  return { bookCount: catalog.length, libraryCount: libraries.length };
}

export function getLibraries() {
  return libraries;
}

export function getLibraryLabel(libraryId) {
  const lib = libraries.find((l) => l.id === libraryId);
  return lib ? lib.label : libraryId;
}

export function getCategoriesForLibrary(libraryId) {
  const cats = tree[libraryId] || {};
  return Object.keys(cats)
    .map((code) => ({
      code,
      label: categories[code] || code,
      bookCount: (byLibCategory.get(`${libraryId}|${code}`) || cats[code] || []).length,
    }))
    .sort((a, b) => a.label.localeCompare(b.label, "ru"));
}

export function getCategoryLabel(code) {
  return categories[code] || code;
}

export function getBooksForCategory(libraryId, categoryCode) {
  return byLibCategory.get(`${libraryId}|${categoryCode}`) || [];
}

export function getBookByPath(path) {
  return byPath.get(path) || null;
}

// Raw disk listing for a folder, independent of catalog metadata (Files view).
// path is [] (root: libraries), [libraryId], or [libraryId, categoryCode].
export function listFolder(path) {
  if (path.length === 0) {
    return libraries.map((l) => ({ type: "dir", name: l.id, label: l.label, count: l.bookCount }));
  }
  if (path.length === 1) {
    const cats = tree[path[0]] || {};
    return Object.keys(cats)
      .sort()
      .map((code) => ({ type: "dir", name: code, label: categories[code] || code, count: cats[code].length }));
  }
  if (path.length === 2) {
    const files = (tree[path[0]] || {})[path[1]] || [];
    return files.map((f) => {
      const fullPath = `${path[0]}/${path[1]}/${f.n}`;
      const meta = byPath.get(fullPath);
      return { type: "file", name: f.n, size: f.s, path: fullPath, meta };
    });
  }
  return [];
}

export function getAllCatalog() {
  return catalog;
}

export function getTotalBookCount() {
  return catalog.length;
}
